<?php
declare(strict_types=1);
function migrationChecks(PDO $admin,string $target,string $root,string $dsn):void{
    if(!extension_loaded('sqlite3')||!extension_loaded('pdo_sqlite')){echo "SKIP Legacy migration: optional sqlite3/pdo_sqlite extensions unavailable.\n";return;}
    $source=$target.'/legacy.sqlite';$sqlite=new PDO('sqlite:'.$source);$sqlite->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);
    $schema=['products'=>['id'=>'TEXT PRIMARY KEY','slug'=>'TEXT','data'=>'TEXT'],'variants'=>['id'=>'TEXT PRIMARY KEY','product_id'=>'TEXT','data'=>'TEXT'],'settings'=>['id'=>'INTEGER PRIMARY KEY','data'=>'TEXT'],'orders'=>['id'=>'TEXT PRIMARY KEY','code'=>'TEXT','token_hash'=>'TEXT','data'=>'TEXT'],'order_receipts'=>['order_id'=>'TEXT PRIMARY KEY','content'=>'TEXT','updated_at'=>'TEXT'],'idempotency'=>['key'=>'TEXT PRIMARY KEY','request_hash'=>'TEXT','response'=>'TEXT'],'users'=>['id'=>'TEXT PRIMARY KEY','email'=>'TEXT','name'=>'TEXT','role'=>'TEXT','password_hash'=>'TEXT'],'sessions'=>['token_hash'=>'TEXT PRIMARY KEY','user_id'=>'TEXT','expires'=>'INTEGER'],'audit'=>['id'=>'INTEGER PRIMARY KEY','user_id'=>'TEXT','action'=>'TEXT','detail'=>'TEXT','created_at'=>'TEXT']];
    foreach($schema as $table=>$fields){$defs=[];foreach($fields as $key=>$type)$defs[]='"'.$key.'" '.$type;$sqlite->exec('CREATE TABLE "'.$table.'" ('.implode(',',$defs).')');$columns=array_keys($fields);$sql='INSERT INTO "'.$table.'" ("'.implode('","',$columns).'") VALUES('.implode(',',array_fill(0,count($columns),'?')).')';$insert=$sqlite->prepare($sql);foreach($admin->query('SELECT `'.implode('`,`',$columns).'` FROM `'.$table.'`')->fetchAll(PDO::FETCH_NUM) as $row)$insert->execute($row);}
    $userId=$sqlite->query('SELECT id FROM users LIMIT 1')->fetchColumn();$sqlite->prepare('INSERT INTO sessions VALUES(?,?,?)')->execute([str_repeat('a',64),$userId,(int)(microtime(true)*1000)+60000]);$sqlite=null;$before=hash_file('sha256',$source);
    $export=$target.'/legacy-export';
    $command=static function(array $args)use($root):array{$process=proc_open(array_merge([PHP_BINARY,$root.'/tools/sqlite-to-mysql.php'],$args),[1=>['pipe','w'],2=>['pipe','w']],$pipes);$output=stream_get_contents($pipes[1]).stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);return [proc_close($process),$output];};
    check('PHP legacy converter checks without modifying SQLite',function()use($command,$source,$before){[$code,$text]=$command(['--source',$source,'--check']);ensure($code===0,$text);ensure(hash_file('sha256',$source)===$before);});
    check('PHP legacy converter exports a consistent snapshot',function()use($command,$source,$export,$before){[$code,$text]=$command(['--source',$source,'--export','--out',$export]);ensure($code===0,$text);ensure(hash_file('sha256',$source)===$before);ensure(is_file($export.'/source-backup.sqlite'));$m=json_decode(file_get_contents($export.'/manifest.json'),true);ensure($m['tables']['sessions']['count']===0);ensure($m['revokedSessions']===1);ensure(count($m['tables'])===9);});
    $database='fillico_test_migration_'.bin2hex(random_bytes(4));
    $db=new PDO($dsn,getenv('FILLICO_TEST_USER')?:'root',getenv('FILLICO_TEST_PASSWORD')?:'',[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
    try{
        $db->exec('CREATE DATABASE `'.$database.'` CHARACTER SET utf8mb4 COLLATE utf8mb4_bin');$db->exec('USE `'.$database.'`');$db->exec(file_get_contents($root.'/fillico-private/migrations/001_initial.sql'));
        check('PHP legacy export imports all nine tables with matching content',function()use($db,$export,$target,$database,$dsn,$root){
            $stmt=$db->query(file_get_contents($export.'/data.sql'));do{$stmt->fetchAll();}while($stmt->nextRowset());$stmt->closeCursor();
            $stmt=$db->query(file_get_contents($export.'/verify.sql'));do{foreach($stmt->fetchAll(PDO::FETCH_ASSOC) as $r)if(isset($r['count_ok']))ensure((int)$r['count_ok']===1&&(int)$r['content_ok']===1,json_encode($r));}while($stmt->nextRowset());$stmt->closeCursor();
            $file=$target.'/migration-config.php';file_put_contents($file,'<?php return '.var_export(['dsn'=>$dsn.';dbname='.$database,'db_user'=>getenv('FILLICO_TEST_USER')?:'root','db_password'=>getenv('FILLICO_TEST_PASSWORD')?:'','uploads_dir'=>$export.'/uploads'],true).';');
            $process=proc_open([PHP_BINARY,$root.'/tools/verify-import.php',$file,$export.'/manifest.json'],[1=>['pipe','w'],2=>['pipe','w']],$pipes);$text=stream_get_contents($pipes[1]).stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);ensure(proc_close($process)===0,$text);ensure((int)$db->query('SELECT COUNT(*) FROM sessions')->fetchColumn()===0);
        });
        check('PHP legacy export refuses importing into a nonempty database',function()use($db,$export){$before=(int)$db->query('SELECT COUNT(*) FROM orders')->fetchColumn();$stmt=$db->query(file_get_contents($export.'/data.sql'));$stop=false;do{foreach($stmt->fetchAll(PDO::FETCH_ASSOC) as $r)if(isset($r['migration_guard']))$stop=str_contains($r['migration_guard'],'STOP');}while($stmt->nextRowset());$stmt->closeCursor();ensure($stop);ensure((int)$db->query('SELECT COUNT(*) FROM orders')->fetchColumn()===$before);});
    }finally{$db->exec('DROP DATABASE IF EXISTS `'.$database.'`');}
}
